# -*- coding: utf-8 -*-

import re
path='src/lalka-2/work/chapter-01/scaffold.txt'
tr={
165:'— О, дуже кольорові.',166:'— Але запилені...',167:'— О, дуже запилені, — відповів управитель.',168:'— І гадаю, — додав я, — що цей молодий чоловік дотримає слова щодо несплати за квартиру, так?',169:'— Пане, — вигукнув управитель, — він — дрібниця. Каже, що не заплатить, і не платить; а ті двоє нічого не кажуть і теж не платять. Це, пане Ржецький, надзвичайні мешканці!... Вони єдині ніколи мене не підводять.',170:'Мимоволі, і сам не знаю чому, я похитав головою, хоча передчуваю: якби був власником такого дому, то хитав би головою цілий день.',171:'— То тут ніхто не платить, або принаймні не платить регулярно? — запитав я екс-поміщика.',172:'— І нема чому дивуватися, — відповів пан Вірський. — У домі, де вже стільки років кредитори збирають квартирну плату, навіть найчесніший мешканець мусить зіпсуватися<sup>590</sup>. Попри це, маємо кількох дуже пунктуальних, наприклад баронесу Кжешовську...',173:'— Що?!... — вигукнув я. — А й справді, баронеса тут мешкає... Вона навіть хотіла купити цей дім...',174:'— І купить, — прошепотів управитель. — Тільки, панове, тримайтеся міцно!... Купить, хай навіть доведеться віддати весь свій маєток... А маєток чималий, хоч пан барон добряче його пошматував...',175:'Я й далі стояв на сходовому майданчику, під вікном із жовтими, червоними й блакитними шибками. Стояв, заглиблений у спогад про пані баронесу, яку бачив у житті лише кілька разів і яка завжди видавалася мені дуже ексцентричною особою.',176:'Уміє бути побожною й запеклою, покірною й грубою...',177:'— Що це за жінка, пане Вірський? — спитав я. — Незвичайна жінка, пане...',178:'— Як усі істерички, — пробурмотів екс-поміщик. — Донечку втратила, чоловік покинув... Самі скандали!...',179:'— Ходімо до неї, пане, — сказав я, спускаючись на другий поверх. Почувався таким хоробрим, що баронеса не лише не лякала мене, а майже вабила.',180:'Та коли ми стали перед дверима й управитель подзвонив, у мене звело литки. Не міг зрушити з місця і лише тому не втік. За мить уся відвага мене покинула, я згадав сцени з торгів...',181:'У замку повернувся ключ, дзенькнула засувка, і в прочинених дверях з’явилося обличчя ще не старої дівчини, одягненої в білий чепчик.',182:'— А хто там? — спитала дівчина.',183:'— Я, управитель.',184:'— Чого пан хоче?',}
lines=open(path,encoding='utf-8').read().splitlines(); i=-1; out=[]
for ln in lines:
 if ln.startswith('**PL:**'): i+=1
 if ln=='**UA:**' and i in tr: ln='**UA:** '+tr[i]
 out.append(ln)
open(path,'w',encoding='utf-8').write('\n'.join(out))
print('filled',len(tr),'units')
